arguments.new_string:
def _read_export(path, cfg: dict) -> pd.DataFrame:
    df = pd.read_csv(path, dtype={"utc_offset": str})
    if "interval_end_local" in df:
        # Labelled by the interval's END (Litware, data/litware/README.txt): a 09:20 row covers 09:00-09:20.
        if "utc_offset" not in df:
            raise SystemExit(f"{path}: interval_end_local needs a utc_offset column")
        end = _from_offsets(pd.to_datetime(df["interval_end_local"]), df["utc_offset"], cfg["tz"], path)
        df["interval_start_utc"] = end - pd.Timedelta(minutes=cfg["interval_minutes"])
        return df[["queue", "interval_start_utc", "volume", "aht_sec"]]
    local = pd.to_datetime(df["interval_start_local"])
    if "utc_offset" in df:
        df["interval_start_utc"] = _from_offsets(local, df["utc_offset"], cfg["tz"], path)

