def queue_start_ok(template: Template, queue: str, cfg: dict) -> bool:
    """True if every segment of the template starts at or after the queue's earliest local hour
    (`queue_earliest`, e.g. {email: 9}: no agent is scheduled on email before 09:00)."""
    lo = (cfg.get("queue_earliest") or {}).get(queue)
    return lo is None or all(s >= lo for s, _ in template.segments)

