def schedule_week(req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str) -> list[Shift]:
    """Greedy placement, then breaks. With `cover_breaks` (SOW §2.3 puts each break where the gross
    surplus is largest, and the break then takes one agent off the queue): an interval left short
    net of breaks gets the shortfall added to its coverage target, and the week is placed again."""
    extra: dict[tuple[str, object], int] = {}
    shifts = _schedule_once(req, cfg, agents, week, extra)
    if not cfg.get("cover_breaks"):
