    for _ in range(COVER_ROUNDS):
        short = _net_shortfalls(req, shifts, cfg, agents)
        if not short:
            break
        for key, n in short.items():
            extra[key] = extra.get(key, 0) + n
        shifts = _schedule_once(req, cfg, agents, week, extra)
    return shifts


