"""Independent check of Litware outputs against docs/LITWARE_SOW.md (reads raw data, not wfm.evaluate)."""
import sys, json, math
from collections import defaultdict
from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo
import pandas as pd
sys.path.insert(0, "/app")
from wfm.staffing.erlang import required_agents, service_level  # the service's Erlang C (SOW §1.2 model)

week = sys.argv[1]
LON = ZoneInfo("Europe/London"); UTC = timezone.utc
mon = datetime.fromisocalendar(int(week[:4]), int(week[-2:]), 1)
wk_start = datetime(mon.year, mon.month, mon.day, tzinfo=LON)
wk_end = wk_start + timedelta(days=7)
grid = []
t = wk_start.astimezone(UTC)
while t < wk_end.astimezone(UTC):
    grid.append(t); t += timedelta(minutes=20)
G = 20

# demand, from the raw export: label = interval END local, offset authoritative
raw = pd.read_csv(f"/app/data/litware/export_{week}.csv", dtype={"utc_offset": str})
raw["end_utc"] = [datetime.strptime(l, "%Y-%m-%d %H:%M").replace(tzinfo=UTC) - (1 if o[0] == "-" else -1) * timedelta(hours=int(o[1:3]), minutes=int(o[4:6]))
                  for l, o in zip(raw["interval_end_local"], raw["utc_offset"])]
raw["start_utc"] = raw["end_utc"] - timedelta(minutes=G)
dem = {(r.queue, r.start_utc): (float(r.volume), float(r.aht_sec)) for r in raw.itertuples()}
TGT = {"priority": (0.90, 30), "standard": (0.80, 30), "email": (0.80, 300)}
req = {}
for q in TGT:
    aht_vals = [a for (qq, t0), (v, a) in dem.items() if qq == q]
    for t0 in grid:
        v, a = dem.get((q, t0), (0.0, 300.0))
        req[(q, t0)] = 0 if v <= 0 else required_agents(v, G * 60, a, TGT[q][0], TGT[q][1], 0.85)
def loc(t): return t.astimezone(LON)
op = [t for t in grid if 7 <= loc(t).hour + loc(t).minute / 60 < 21]
req_hours = sum(req.values()) * G / 60
print(f"intervals {len(grid)} operating {len(op)} required_hours {req_hours:.1f}")

# schedule
S = pd.read_csv(f"/app/out/litware/schedule.csv")
agents = pd.read_csv("/app/data/agents/litware.csv")
skills = {r.agent_id: set(r.skills.split(";")) for r in agents.itertuples()}
contract = {r.agent_id: r.contract for r in agents.itertuples()}
S["s"] = pd.to_datetime(S.segment_start_utc, utc=True).dt.to_pydatetime()
S["e"] = pd.to_datetime(S.segment_end_utc, utc=True).dt.to_pydatetime()
S["b"] = pd.to_datetime(S.break_start_utc.where(S.break_start_utc.notna(), None), utc=True).dt.to_pydatetime()
viol = defaultdict(int); problems = []
def bad(rule, msg):
    viol[rule] += 1
    if len(problems) < 15: problems.append(f"{rule}: {msg}")

for r in S.itertuples():
    if r.queue not in skills.get(r.agent_id, set()): bad("skill", r.agent_id)
    if r.queue == "email" and loc(r.s).hour < 9: bad("email_before_9", f"{r.agent_id} {r.s}")
    if (loc(r.s).date() != loc(r.e - timedelta(seconds=1)).date()): bad("crosses_midnight", r.agent_id)
    if r.s.minute % 20 or r.e.minute % 20: bad("grid", f"{r.agent_id} {r.s}")
S["day"] = S.s.map(lambda x: loc(x).date())
shifts = []
for (aid, day), g in S.groupby(["agent_id", "day"]):
    g = g.sort_values("s")
    segs = list(zip(g.s, g.e)); qs = set(g.queue)
    if len(qs) > 1: bad("one_queue_per_shift", aid)
    hrs = sum((e - s).total_seconds() for s, e in segs) / 3600
    start, end = segs[0][0], segs[-1][1]
    for (s1, e1), (s2, e2) in zip(segs, segs[1:]):
        if s2 < e1: bad("overlap", aid)
    split = len(segs) > 1
    if split and contract[aid] != "PT": bad("split_contract", aid)
    brk = g[g.break_minutes > 0]
    if hrs >= 6:
        ok = len(brk) == 1 and int(brk.break_minutes.iloc[0]) == 20 and 2 * 3600 <= (brk.b.iloc[0] - start).total_seconds() <= 5 * 3600
        if not ok: bad("break_rule", f"{aid} {day} {hrs}")
    elif len(brk): bad("break_rule", f"short shift with break {aid} {day}")
    shifts.append(dict(aid=aid, day=day, start=start, end=end, hours=hrs, queue=qs.pop(), brk=(brk.b.iloc[0] if len(brk) else None), segs=segs, contract=contract[aid]))
byagent = defaultdict(list)
for sh in shifts: byagent[sh["aid"]].append(sh)
for aid, L in byagent.items():
    L.sort(key=lambda x: x["start"])
    cap = 40 if contract[aid] == "FT" else 24
    if sum(x["hours"] for x in L) > cap + 1e-9: bad("weekly_hours", aid)
    for a, b in zip(L, L[1:]):
        if (b["start"] - a["end"]).total_seconds() < 11 * 3600: bad("rest_11h", f"{aid} {a['day']}->{b['day']}")
    days = sorted(x["day"] for x in L); run = 1
    for d1, d2 in zip(days, days[1:]):
        run = run + 1 if (d2 - d1).days == 1 else 1
        if run > 5: bad("consecutive_days", aid); break
# SOW §2.10 shapes: template segments in local hours
SHAPES = {((9, 17),), ((13, 21),), ((7, 13),), ((15, 21),), ((10, 14),), ((8, 12), (16, 20))}
for sh in shifts:
    shape = tuple((loc(s).hour, loc(e).hour) for s, e in sh["segs"])
    if shape not in SHAPES: bad("template_shape", str(shape))

# coverage: gross per queue per interval, and on-break
gross = defaultdict(int); onb = defaultdict(int)
for sh in shifts:
    for s, e in sh["segs"]:
        for t0 in grid:
            if s <= t0 < e: gross[(sh["queue"], t0)] += 1
    if sh["brk"] is not None:
        for t0 in grid:
            if sh["brk"] <= t0 < sh["brk"] + timedelta(minutes=20): onb[(sh["queue"], t0)] += 1
# §2.3 surplus rule: break at max gross surplus within its window
for sh in shifts:
    if sh["brk"] is None: continue
    cands = [t0 for t0 in grid if sh["start"] + timedelta(hours=2) <= t0 <= sh["start"] + timedelta(hours=5)
             and any(s <= t0 and t0 + timedelta(minutes=20) <= e for s, e in sh["segs"])]
    surplus = lambda t0: gross[(sh["queue"], t0)] - req.get((sh["queue"], t0), 0)
    best = max(surplus(t0) for t0 in cands)
    if surplus(sh["brk"]) != best: bad("break_surplus_rule", f"{sh['aid']} {sh['day']}")
# §2.4 priority floor
for t0 in op:
    if gross[("priority", t0)] < 2: bad("priority_cover", str(t0))

# exceptions per §2.6: provably impossible intervals
exc = set()
for q in TGT:
    for t0 in op:
        if req[(q, t0)] > 0 and q == "email" and loc(t0).hour < 9: exc.add((q, t0))
# attainment §1.6 (operating intervals, §2.6 left out), requirement met net of breaks
att, under = {}, 0.0
for q in TGT:
    met = tot = 0
    for t0 in op:
        if (q, t0) in exc: continue
        tot += 1
        net = gross[(q, t0)] - onb[(q, t0)]
        if net >= req[(q, t0)]: met += 1
        under += max(0, req[(q, t0)] - net) * G / 60
    att[q] = round(met / tot, 3)
hours = sum(sh["hours"] for sh in shifts)
print("violations:", dict(viol) or "none")
for p in problems: print("  ", p)
print("attainment (recomputed):", att, "min", min(att.values()), "PASS" if min(att.values()) >= 0.95 else "FAIL")
print(f"scheduled_hours {hours:.1f} required {req_hours:.1f} ratio {hours/req_hours:.3f}", "PASS" if hours <= 1.45 * req_hours else "FAIL")
print("exceptions (recomputed):", len(exc), "agents", len(byagent))
ev = json.load(open("/app/out/litware/eval.json"))
print("eval.json sla", ev["sla"], "diff max", max(abs(ev["sla"][q] - att[q]) for q in TGT))
print("eval.json exceptions match:", sorted(f"{q} {t0:%Y-%m-%dT%H:%M:%SZ}" for q, t0 in exc) == sorted(ev["exceptions"]))
print("eval.json required_hours", ev["required_hours"], "recomputed", round(req_hours, 1), "scheduled", ev["scheduled_hours"], round(hours, 1), "under", ev["understaffed_interval_hours"], round(under, 1))
EOF
cd /tmp/verify && python -I verify_litware.py 2027-W11 2>&1 | tail -30

